func imageInner(p ImageProps) image.ImageProps {
	in := p.ImageProps
	in.Class = Join(Rc("image", map[string]string{"aspect": p.Aspect, "fit": p.Fit, "position": p.Position, "size": p.Size, "variant": p.Variant}), p.ImageProps.Class)
